namespace Notrelix.Application.Features.Collaboration.Attachments.Services;

/// <summary>
/// Server-owned object key scheme for attachment files:
/// <c>{accountId:N}/{workspaceId:N}/attachments/{objectId:N}</c>.
/// The key is generated by the server, carries the tenant prefix, and never contains any
/// part of the client-supplied file name. A key identifies an object; it is not permission.
/// </summary>
public static class AttachmentStorageKey
{
    private const string Segment = "attachments";

    private static readonly System.Text.RegularExpressions.Regex KeyPattern = new(
        "^[0-9a-f]{32}/[0-9a-f]{32}/" + Segment + "/[0-9a-f]{32}$",
        System.Text.RegularExpressions.RegexOptions.CultureInvariant | System.Text.RegularExpressions.RegexOptions.NonBacktracking);

    /// <summary>
    /// True when <paramref name="key"/> has exactly the shape <see cref="Create"/> produces. Lets a
    /// storage sweep recognise attachment objects without touching other objects in the same store.
    /// </summary>
    public static bool IsAttachmentKey(string key) => KeyPattern.IsMatch(key);

    public static string Create(Guid accountId, Guid workspaceId) =>
        $"{accountId:N}/{workspaceId:N}/{Segment}/{Guid.CreateVersion7():N}";

    /// <summary>
    /// Defence in depth for reads: the stored key must sit under the tenant prefix of the
    /// request scope that resolved the attachment row.
    /// </summary>
    public static bool BelongsTo(string key, Guid accountId, Guid workspaceId) =>
        key.StartsWith($"{accountId:N}/{workspaceId:N}/{Segment}/", StringComparison.Ordinal);
}
